const metrics = $json;
const callbackRate = metrics.missedCalls ? Math.round((metrics.newPatientCallbacks / metrics.missedCalls) * 100) : 0;
const digest = `Dental Weekly Practice Digest
Period: ${metrics.period}
Missed calls: ${metrics.missedCalls}
New-patient callbacks: ${metrics.newPatientCallbacks} (${callbackRate}%)
No-shows: ${metrics.noShows}
Late cancellations: ${metrics.lateCancellations}
Recall opportunities: ${metrics.recallOpportunities}
Treatment plans needing follow-up: ${metrics.treatmentPlansNeedingFollowUp}
Schedule gaps: ${metrics.scheduleGaps}
Review opportunities: ${metrics.reviewOpportunities}
Workflow failures: ${metrics.workflowFailures}`;
return [{ json: { ...metrics, callbackRate, digest } }];
